using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigurationResourceProvider : IResourceProvider
{
    public IReadOnlyList<McpResourceTemplate> GetResourceTemplates() => [];

    public IReadOnlyList<McpResource> GetResources() =>
    [
        new McpResource
        {
            Uri = "config://app/settings",
            Name = "Application Settings",
            Description = "Returns current application configuration data",
            MimeType = "application/json"
        }
    ];

    public Task<ReadResourceResult> ReadResourceAsync(
        string uri, CancellationToken cancellationToken = default)
    {
        if (uri == "config://app/settings")
        {
            var config = new
            {
                AppName = "McpHttpServer",
                Version = "1.0.0",
                Features = new { EnableLogging = true, MaxRetries = 3 },
                Environment = "production"
            };

            return Task.FromResult(new ReadResourceResult
            {
                Contents =
                [
                    new TextResourceContents
                    {
                        Uri = uri,
                        MimeType = "application/json",
                        Text = JsonSerializer.Serialize(config, new JsonSerializerOptions
                        {
                            WriteIndented = true
                        })
                    }
                ]
            });
        }

        throw new McpException($"Resource not found: {uri}");
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server status and uptime")]
    public static object GetStatus()
    {
        return new
        {
            Status = "healthy",
            StartedAt = DateTime.UtcNow,
            MachineName = Environment.MachineName
        };
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

